#include "../../../include/ds_dynamic_stack/header.h"

// ========== Created - Assertion Operations ==========

// Asserts that two stacks have equal contents using stacks_equal function
void helper_assert_stack_equal(DArrayStack *stack1, DArrayStack *stack2) {
    int result = stacks_equal(stack1, stack2);
    assert(result == 1);
}

// Asserts that a stack has the expected capacity
void helper_assert_stack_capacity(DArrayStack *stack, int expected_capacity) {
    int actual_capacity = show_capacity(stack);
    assert(actual_capacity == expected_capacity);
}

// Asserts that a stack has the expected number of elements
void helper_assert_stack_size(DArrayStack *stack, int expected_size) {
    int actual_size = stack_size(stack);
    assert(actual_size == expected_size);
}

// Asserts that a stack is empty (or NULL)
void helper_assert_stack_empty(DArrayStack *stack) {
    int empty = isempty(stack);
    assert(empty == 1);
}

// Asserts that a stack contains a specific value
void helper_assert_stack_contains(DArrayStack *stack, int value) {
    int contains = stack_contains(stack, value);
    assert(contains == 1);
}

// Asserts that the top element of a stack matches the expected value
void helper_assert_stack_peek(DArrayStack *stack, int expected_value) {
    int success = 0;
    int top_value = peek(stack, &success);
    assert(success == 1);
    assert(top_value == expected_value);
}

// Asserts that popping from a stack returns the expected value and updates stack correctly
void helper_assert_stack_pop(DArrayStack *stack, int expected_value) {
    int success = 0;
    int popped_value = pop(stack, &success);
    assert(success == 1);
    assert(popped_value == expected_value);
}

// Asserts that the string representation of a stack matches the expected string
void helper_assert_stack_to_string(DArrayStack *stack, const char *expected_string) {
    int buffer_size = 256;
    char *buffer = malloc(buffer_size * sizeof(char));
    int result = stack_to_string(stack, buffer, buffer_size);
    assert(result != -1);
    assert(strcmp(buffer, expected_string) == 0);
    free(buffer);
}

// ========== Searched From Pool - Utility Operations ==========

// Function: capture_stdout_start (from helper pool)
stdout_capture_t *capture_stdout_start(void) {
    stdout_capture_t *cap = malloc(sizeof(stdout_capture_t));
    if (!cap) return NULL;
    cap->buffer = NULL;
    cap->buffer_size = 0;
    /* Create a pipe */
    int pipefd[2];
    if (pipe(pipefd) == -1) {
        free(cap);
        return NULL;
    }
    cap->pipe_read_fd = pipefd[0];
    cap->pipe_write_fd = pipefd[1];
    /* Save original stdout */
    cap->saved_stdout_fd = dup(STDOUT_FILENO);
    if (cap->saved_stdout_fd == -1) {
        close(cap->pipe_read_fd);
        close(cap->pipe_write_fd);
        free(cap);
        return NULL;
    }
    /* Redirect stdout to the pipe write end */
    if (dup2(cap->pipe_write_fd, STDOUT_FILENO) == -1) {
        close(cap->saved_stdout_fd);
        close(cap->pipe_read_fd);
        close(cap->pipe_write_fd);
        free(cap);
        return NULL;
    }
    return cap;
}

// Function: capture_stdout_stop (from helper pool)
char *capture_stdout_stop(stdout_capture_t *cap) {
    if (!cap) return NULL;
    /* Flush stdout to ensure all output is written to pipe */
    fflush(stdout);
    /* Close write end of pipe to signal EOF */
    close(cap->pipe_write_fd);
    /* Restore original stdout */
    dup2(cap->saved_stdout_fd, STDOUT_FILENO);
    close(cap->saved_stdout_fd);
    /* Read captured output from pipe */
    size_t total_read = 0;
    size_t buffer_capacity = 1024;
    char *buffer = malloc(buffer_capacity);
    if (!buffer) {
        close(cap->pipe_read_fd);
        free(cap);
        return NULL;
    }
    ssize_t bytes_read;
    while ((bytes_read = read(cap->pipe_read_fd, buffer + total_read,
                               buffer_capacity - total_read - 1)) > 0) {
        total_read += bytes_read;
        if (total_read >= buffer_capacity - 1) {
            buffer_capacity *= 2;
            char *new_buffer = realloc(buffer, buffer_capacity);
            if (!new_buffer) {
                free(buffer);
                close(cap->pipe_read_fd);
                free(cap);
                return NULL;
            }
            buffer = new_buffer;
        }
    }
    buffer[total_read] = '\0';
    close(cap->pipe_read_fd);
    free(cap);
    return buffer;
}

