void assert_stdout_equals(stdout_capture_t *cap, const char *expected) {
    char *actual = capture_stdout_stop(cap);
    if (actual == NULL) {
        fprintf(stderr, "Stdout capture failed
");
        exit(1);
    }
    if (strcmp(actual, expected) != 0) {
        fprintf(stderr, "Stdout assertion failed:
");
        fprintf(stderr, "  Expected: "%s"
", expected);
        fprintf(stderr, "  Actual:   "%s"
", actual);
        free(actual);
        exit(1);
    }
    free(actual);
}

// Function: assert_stdout_contains (from helper pool)
void assert_stdout_contains(stdout_capture_t *cap, const char *expected_substring) {
    char *actual = capture_stdout_stop(cap);
    if (actual == NULL) {
        fprintf(stderr, "Stdout capture failed
");
        exit(1);
    }
    if (strstr(actual, expected_substring) == NULL) {
        fprintf(stderr, "Stdout assertion failed (substring not found):
");
        fprintf(stderr, "  Expected substring: "%s"
", expected_substring);
        fprintf(stderr, "  Actual output:      "%s"
", actual);
        free(actual);
        exit(1);
    }
    free(actual);
}

// Function: assert_stdout_not_empty (from helper pool)
void assert_stdout_not_empty(stdout_capture_t *cap) {
    char *actual = capture_stdout_stop(cap);
    if (actual == NULL) {
        fprintf(stderr, "Stdout capture failed
");
        exit(1);
    }
    if (strlen(actual) == 0) {
        fprintf(stderr, "Stdout assertion failed: output was empty
");
        free(actual);
        exit(1);
    }
    free(actual);
}

// ========== Created - Utility Operations ==========

// Creates a stack and pushes an array of values onto it
DArrayStack *helper_create_stack_with_values(int *values, int size, int initial_capacity) {
    DArrayStack *stack = create_stack(initial_capacity);
    if (stack == NULL) {
        return NULL;
    }
    for (int i = 0; i < size; i++) {
        push(stack, values[i]);
    }
    return stack;
}

// Creates a stack with random integer values
